package com.smarthospital.controller;
import com.smarthospital.model.User;import javax.servlet.*;import javax.servlet.annotation.*;import javax.servlet.http.*;import java.io.*;
@WebFilter(urlPatterns={"/staff","/duties","/allocation","/reports","/supervisors"}) public class ManagerFilter implements Filter{public void doFilter(ServletRequest a,ServletResponse b,FilterChain f)throws IOException,ServletException{User u=(User)((HttpServletRequest)a).getSession().getAttribute("user");String path=((HttpServletRequest)a).getServletPath();if(u==null){((HttpServletResponse)b).sendRedirect(((HttpServletRequest)a).getContextPath()+"/login.jsp");return;}if("STAFF".equals(u.role())||("/supervisors".equals(path)&&!"ADMIN".equals(u.role()))){((HttpServletResponse)b).sendError(403,"Manager access required");return;}f.doFilter(a,b);}}
